/**
 * Editor Store
 * Manages timeline, selection, playback, and editing state
 */

import { create } from 'zustand';
import { subscribeWithSelector } from 'zustand/middleware';
import type { FrameRange } from '../api/types';

/** Playback state */
export type PlaybackState = 'stopped' | 'playing' | 'paused';

/** Selection mode for frames */
export type SelectionMode = 'single' | 'range' | 'multi';

/** Tool types available in editor */
export type EditorTool =
  | 'select'
  | 'crop'
  | 'resize'
  | 'flip'
  | 'rotate'
  | 'text'
  | 'drawing'
  | 'shapes'
  | 'blur'
  | 'watermark'
  | 'border'
  | 'shadow'
  | 'keystrokes'
  | 'cursor'
  | 'progress';

/** Zoom level preset */
export type ZoomPreset = 'fit' | 'fill' | '25' | '50' | '75' | '100' | '150' | '200' | '400';

interface EditorState {
  // Frame selection
  selectedFrameIds: string[];
  selectionMode: SelectionMode;
  selectionRange: FrameRange | null;
  lastSelectedFrameId: string | null;

  // Playback
  playbackState: PlaybackState;
  currentFrameIndex: number;
  playbackSpeed: number; // 0.25 to 4.0
  isLooping: boolean;

  // Timeline
  timelineZoom: number; // 0.5 to 4.0
  timelineScrollPosition: number;
  thumbnailSize: 'small' | 'medium' | 'large';
  showFrameNumbers: boolean;
  showFrameDelays: boolean;

  // Editor canvas
  canvasZoom: number;
  canvasZoomPreset: ZoomPreset;
  canvasPanX: number;
  canvasPanY: number;
  showGrid: boolean;
  gridSize: number;
  snapToGrid: boolean;

  // Current tool
  currentTool: EditorTool;
  toolOptions: Record<string, unknown>;

  // Clipboard
  clipboardFrameIds: string[];
  clipboardOperation: 'copy' | 'cut' | null;

  // Undo/Redo
  canUndo: boolean;
  canRedo: boolean;
  historyIndex: number;

  // UI state
  isSidebarCollapsed: boolean;
  isTimelineCollapsed: boolean;
  activePanel: 'frames' | 'effects' | 'export' | 'settings';

  // Preview
  showOnionSkin: boolean;
  onionSkinFramesBefore: number;
  onionSkinFramesAfter: number;
  onionSkinOpacity: number;
}

interface EditorActions {
  // Frame selection
  selectFrame: (frameId: string, addToSelection?: boolean) => void;
  selectFrames: (frameIds: string[]) => void;
  selectFrameRange: (startId: string, endId: string) => void;
  selectAllFrames: (frameIds: string[]) => void;
  deselectFrame: (frameId: string) => void;
  clearSelection: () => void;
  setSelectionMode: (mode: SelectionMode) => void;
  invertSelection: (allFrameIds: string[]) => void;

  // Playback
  play: () => void;
  pause: () => void;
  stop: () => void;
  togglePlayback: () => void;
  setCurrentFrameIndex: (index: number) => void;
  nextFrame: () => void;
  previousFrame: () => void;
  goToFirstFrame: () => void;
  goToLastFrame: (totalFrames: number) => void;
  setPlaybackSpeed: (speed: number) => void;
  setIsLooping: (looping: boolean) => void;

  // Timeline
  setTimelineZoom: (zoom: number) => void;
  setTimelineScrollPosition: (position: number) => void;
  setThumbnailSize: (size: 'small' | 'medium' | 'large') => void;
  setShowFrameNumbers: (show: boolean) => void;
  setShowFrameDelays: (show: boolean) => void;

  // Canvas
  setCanvasZoom: (zoom: number) => void;
  setCanvasZoomPreset: (preset: ZoomPreset) => void;
  zoomIn: () => void;
  zoomOut: () => void;
  fitToWindow: () => void;
  resetZoom: () => void;
  setCanvasPan: (x: number, y: number) => void;
  setShowGrid: (show: boolean) => void;
  setGridSize: (size: number) => void;
  setSnapToGrid: (snap: boolean) => void;

  // Tools
  setCurrentTool: (tool: EditorTool) => void;
  setToolOption: (key: string, value: unknown) => void;
  clearToolOptions: () => void;

  // Clipboard
  copyFrames: (frameIds: string[]) => void;
  cutFrames: (frameIds: string[]) => void;
  clearClipboard: () => void;
  hasClipboardContent: () => boolean;

  // History
  setCanUndo: (canUndo: boolean) => void;
  setCanRedo: (canRedo: boolean) => void;
  setHistoryIndex: (index: number) => void;

  // UI
  toggleSidebar: () => void;
  toggleTimeline: () => void;
  setActivePanel: (panel: 'frames' | 'effects' | 'export' | 'settings') => void;

  // Onion skin
  setShowOnionSkin: (show: boolean) => void;
  setOnionSkinFramesBefore: (frames: number) => void;
  setOnionSkinFramesAfter: (frames: number) => void;
  setOnionSkinOpacity: (opacity: number) => void;

  // Reset
  reset: () => void;
}

const initialState: EditorState = {
  selectedFrameIds: [],
  selectionMode: 'single',
  selectionRange: null,
  lastSelectedFrameId: null,
  playbackState: 'stopped',
  currentFrameIndex: 0,
  playbackSpeed: 1.0,
  isLooping: true,
  timelineZoom: 1.0,
  timelineScrollPosition: 0,
  thumbnailSize: 'medium',
  showFrameNumbers: true,
  showFrameDelays: false,
  canvasZoom: 1.0,
  canvasZoomPreset: '100',
  canvasPanX: 0,
  canvasPanY: 0,
  showGrid: false,
  gridSize: 16,
  snapToGrid: false,
  currentTool: 'select',
  toolOptions: {},
  clipboardFrameIds: [],
  clipboardOperation: null,
  canUndo: false,
  canRedo: false,
  historyIndex: -1,
  isSidebarCollapsed: false,
  isTimelineCollapsed: false,
  activePanel: 'frames',
  showOnionSkin: false,
  onionSkinFramesBefore: 1,
  onionSkinFramesAfter: 1,
  onionSkinOpacity: 0.3,
};

const ZOOM_LEVELS = [0.25, 0.5, 0.75, 1.0, 1.5, 2.0, 3.0, 4.0];

export const useEditorStore = create<EditorState & EditorActions>()(
  subscribeWithSelector((set, get) => ({
    ...initialState,

    // Frame selection
    selectFrame: (frameId, addToSelection = false) => {
      set((state) => {
        if (addToSelection) {
          const newSelection = state.selectedFrameIds.includes(frameId)
            ? state.selectedFrameIds.filter((id) => id !== frameId)
            : [...state.selectedFrameIds, frameId];
          return { selectedFrameIds: newSelection, lastSelectedFrameId: frameId };
        }
        return { selectedFrameIds: [frameId], lastSelectedFrameId: frameId };
      });
    },

    selectFrames: (frameIds) => set({ selectedFrameIds: frameIds }),

    selectFrameRange: (startId, endId) => {
      set({ selectionRange: { startIndex: parseInt(startId), endIndex: parseInt(endId) } });
    },

    selectAllFrames: (frameIds) => set({ selectedFrameIds: frameIds }),

    deselectFrame: (frameId) =>
      set((state) => ({
        selectedFrameIds: state.selectedFrameIds.filter((id) => id !== frameId),
      })),

    clearSelection: () =>
      set({ selectedFrameIds: [], selectionRange: null, lastSelectedFrameId: null }),

    setSelectionMode: (selectionMode) => set({ selectionMode }),

    invertSelection: (allFrameIds) =>
      set((state) => ({
        selectedFrameIds: allFrameIds.filter((id) => !state.selectedFrameIds.includes(id)),
      })),

    // Playback
    play: () => set({ playbackState: 'playing' }),
    pause: () => set({ playbackState: 'paused' }),
    stop: () => set({ playbackState: 'stopped', currentFrameIndex: 0 }),

    togglePlayback: () => {
      const { playbackState } = get();
      if (playbackState === 'playing') {
        set({ playbackState: 'paused' });
      } else {
        set({ playbackState: 'playing' });
      }
    },

    setCurrentFrameIndex: (currentFrameIndex) => set({ currentFrameIndex }),

    nextFrame: () =>
      set((state) => ({ currentFrameIndex: state.currentFrameIndex + 1 })),

    previousFrame: () =>
      set((state) => ({
        currentFrameIndex: Math.max(0, state.currentFrameIndex - 1),
      })),

    goToFirstFrame: () => set({ currentFrameIndex: 0 }),

    goToLastFrame: (totalFrames) =>
      set({ currentFrameIndex: Math.max(0, totalFrames - 1) }),

    setPlaybackSpeed: (playbackSpeed) =>
      set({ playbackSpeed: Math.min(Math.max(playbackSpeed, 0.25), 4.0) }),

    setIsLooping: (isLooping) => set({ isLooping }),

    // Timeline
    setTimelineZoom: (timelineZoom) =>
      set({ timelineZoom: Math.min(Math.max(timelineZoom, 0.5), 4.0) }),

    setTimelineScrollPosition: (timelineScrollPosition) => set({ timelineScrollPosition }),

    setThumbnailSize: (thumbnailSize) => set({ thumbnailSize }),
    setShowFrameNumbers: (showFrameNumbers) => set({ showFrameNumbers }),
    setShowFrameDelays: (showFrameDelays) => set({ showFrameDelays }),

    // Canvas
    setCanvasZoom: (canvasZoom) => set({ canvasZoom, canvasZoomPreset: 'fit' }),

    setCanvasZoomPreset: (preset) => {
      const zoomMap: Record<ZoomPreset, number | null> = {
        fit: null,
        fill: null,
        '25': 0.25,
        '50': 0.5,
        '75': 0.75,
        '100': 1.0,
        '150': 1.5,
        '200': 2.0,
        '400': 4.0,
      };
      const zoom = zoomMap[preset];
      if (zoom !== null) {
        set({ canvasZoom: zoom, canvasZoomPreset: preset });
      } else {
        set({ canvasZoomPreset: preset });
      }
    },

    zoomIn: () => {
      const { canvasZoom } = get();
      const nextIndex = ZOOM_LEVELS.findIndex((z) => z > canvasZoom);
      if (nextIndex !== -1) {
        set({ canvasZoom: ZOOM_LEVELS[nextIndex] });
      }
    },

    zoomOut: () => {
      const { canvasZoom } = get();
      const prevIndex = [...ZOOM_LEVELS].reverse().findIndex((z) => z < canvasZoom);
      if (prevIndex !== -1) {
        set({ canvasZoom: ZOOM_LEVELS[ZOOM_LEVELS.length - 1 - prevIndex] });
      }
    },

    fitToWindow: () => set({ canvasZoomPreset: 'fit' }),
    resetZoom: () => set({ canvasZoom: 1.0, canvasZoomPreset: '100', canvasPanX: 0, canvasPanY: 0 }),

    setCanvasPan: (canvasPanX, canvasPanY) => set({ canvasPanX, canvasPanY }),
    setShowGrid: (showGrid) => set({ showGrid }),
    setGridSize: (gridSize) => set({ gridSize }),
    setSnapToGrid: (snapToGrid) => set({ snapToGrid }),

    // Tools
    setCurrentTool: (currentTool) => set({ currentTool }),
    setToolOption: (key, value) =>
      set((state) => ({ toolOptions: { ...state.toolOptions, [key]: value } })),
    clearToolOptions: () => set({ toolOptions: {} }),

    // Clipboard
    copyFrames: (frameIds) => set({ clipboardFrameIds: frameIds, clipboardOperation: 'copy' }),
    cutFrames: (frameIds) => set({ clipboardFrameIds: frameIds, clipboardOperation: 'cut' }),
    clearClipboard: () => set({ clipboardFrameIds: [], clipboardOperation: null }),
    hasClipboardContent: () => get().clipboardFrameIds.length > 0,

    // History
    setCanUndo: (canUndo) => set({ canUndo }),
    setCanRedo: (canRedo) => set({ canRedo }),
    setHistoryIndex: (historyIndex) => set({ historyIndex }),

    // UI
    toggleSidebar: () => set((state) => ({ isSidebarCollapsed: !state.isSidebarCollapsed })),
    toggleTimeline: () => set((state) => ({ isTimelineCollapsed: !state.isTimelineCollapsed })),
    setActivePanel: (activePanel) => set({ activePanel }),

    // Onion skin
    setShowOnionSkin: (showOnionSkin) => set({ showOnionSkin }),
    setOnionSkinFramesBefore: (onionSkinFramesBefore) => set({ onionSkinFramesBefore }),
    setOnionSkinFramesAfter: (onionSkinFramesAfter) => set({ onionSkinFramesAfter }),
    setOnionSkinOpacity: (onionSkinOpacity) => set({ onionSkinOpacity }),

    // Reset
    reset: () => set(initialState),
  }))
);

// Selector hooks
export const selectIsPlaying = (state: EditorState) => state.playbackState === 'playing';
export const selectSelectedFrameCount = (state: EditorState) => state.selectedFrameIds.length;
export const selectHasSelection = (state: EditorState) => state.selectedFrameIds.length > 0;

/**
 * Export Store
 * Manages export configuration, presets, encoding progress, and upload state
 */

import { create } from 'zustand';
import { subscribeWithSelector, persist } from 'zustand/middleware';
import type {
  EncodingOptions,
  EncodingProgress,
  ExportPreset,
  PresetCategory,
  OutputFormat,
  UploadConfig,
  UploadProgress,
  UploadResult,
  RecentExport,
  ExportQueueItem,
} from '../api/types';

interface ExportState {
  // Current export configuration
  currentOptions: EncodingOptions | null;
  selectedPresetId: string | null;
  outputPath: string;
  outputFileName: string;

  // Presets
  builtInPresets: ExportPreset[];
  customPresets: ExportPreset[];
  defaultPresetId: string | null;

  // Encoding state
  isEncoding: boolean;
  currentJobId: string | null;
  encodingProgress: EncodingProgress | null;

  // Export queue
  queue: ExportQueueItem[];
  isQueueProcessing: boolean;
  maxConcurrentJobs: number;

  // Upload state
  isUploading: boolean;
  uploadProgress: UploadProgress | null;
  lastUploadResult: UploadResult | null;
  uploadConfig: UploadConfig | null;

  // Recent exports
  recentExports: RecentExport[];
  maxRecentExports: number;

  // UI state
  showAdvancedOptions: boolean;
  selectedFormatTab: OutputFormat;

  // Error state
  error: string | null;
}

interface ExportActions {
  // Configuration
  setCurrentOptions: (options: EncodingOptions) => void;
  updateCurrentOptions: (updates: Partial<EncodingOptions>) => void;
  setSelectedPresetId: (presetId: string | null) => void;
  setOutputPath: (path: string) => void;
  setOutputFileName: (fileName: string) => void;
  applyPreset: (preset: ExportPreset) => void;

  // Presets
  setBuiltInPresets: (presets: ExportPreset[]) => void;
  addCustomPreset: (preset: ExportPreset) => void;
  updateCustomPreset: (presetId: string, updates: Partial<ExportPreset>) => void;
  removeCustomPreset: (presetId: string) => void;
  setDefaultPresetId: (presetId: string | null) => void;
  getPresetById: (presetId: string) => ExportPreset | undefined;
  getPresetsByCategory: (category: PresetCategory) => ExportPreset[];

  // Encoding
  startEncoding: (jobId: string) => void;
  updateEncodingProgress: (progress: EncodingProgress) => void;
  completeEncoding: (success: boolean, error?: string) => void;
  cancelEncoding: () => void;

  // Queue
  addToQueue: (item: Omit<ExportQueueItem, 'id' | 'status' | 'progress' | 'addedAt'>) => void;
  removeFromQueue: (itemId: string) => void;
  clearQueue: () => void;
  updateQueueItem: (itemId: string, updates: Partial<ExportQueueItem>) => void;
  startQueueProcessing: () => void;
  stopQueueProcessing: () => void;

  // Upload
  startUpload: (config: UploadConfig) => void;
  updateUploadProgress: (progress: UploadProgress) => void;
  completeUpload: (result: UploadResult) => void;
  cancelUpload: () => void;
  setUploadConfig: (config: UploadConfig | null) => void;

  // Recent exports
  addRecentExport: (exportInfo: RecentExport) => void;
  removeRecentExport: (exportId: string) => void;
  clearRecentExports: () => void;

  // UI
  setShowAdvancedOptions: (show: boolean) => void;
  toggleAdvancedOptions: () => void;
  setSelectedFormatTab: (format: OutputFormat) => void;

  // Error handling
  setError: (error: string | null) => void;
  clearError: () => void;

  // Reset
  reset: () => void;
  resetProgress: () => void;
}

// Default GIF encoding options
const defaultGifOptions: EncodingOptions = {
  format: 'gif',
  outputPath: '',
  gif: {
    encoder: 'screentogif',
    colorCount: 256,
    quantization: 'medianCut',
    dithering: 'floydSteinberg',
    quality: 80,
    loopCount: 0,
    enableTransparency: false,
    detectUnchangedPixels: true,
    paintTransparent: false,
  },
};

// Built-in presets
const defaultBuiltInPresets: ExportPreset[] = [
  {
    id: 'gif-standard',
    name: 'Standard GIF',
    description: 'Balanced quality and file size',
    category: 'gif',
    isBuiltIn: true,
    isDefault: true,
    options: { ...defaultGifOptions },
  },
  {
    id: 'gif-high-quality',
    name: 'High Quality GIF',
    description: 'Maximum quality, larger file size',
    category: 'gif',
    isBuiltIn: true,
    options: {
      ...defaultGifOptions,
      gif: { ...defaultGifOptions.gif!, colorCount: 256, quality: 100, dithering: 'floydSteinberg' },
    },
  },
  {
    id: 'gif-small-file',
    name: 'Small File GIF',
    description: 'Optimized for smallest file size',
    category: 'gif',
    isBuiltIn: true,
    options: {
      ...defaultGifOptions,
      gif: { ...defaultGifOptions.gif!, colorCount: 128, quality: 60, dithering: 'ordered' },
    },
  },
  {
    id: 'gif-discord',
    name: 'Discord GIF',
    description: 'Optimized for Discord (< 8MB)',
    category: 'social',
    isBuiltIn: true,
    options: {
      ...defaultGifOptions,
      gif: { ...defaultGifOptions.gif!, colorCount: 128, quality: 70 },
    },
  },
  {
    id: 'mp4-standard',
    name: 'Standard MP4',
    description: 'H.264 video with good compression',
    category: 'video',
    isBuiltIn: true,
    options: {
      format: 'mp4',
      outputPath: '',
      video: {
        codec: 'h264',
        bitrate: 5000,
        quality: 23,
        preset: 'medium',
        pixelFormat: 'yuv420p',
        audioEnabled: false,
      },
    },
  },
  {
    id: 'webm-standard',
    name: 'Standard WebM',
    description: 'VP9 video for web use',
    category: 'video',
    isBuiltIn: true,
    options: {
      format: 'webm',
      outputPath: '',
      video: {
        codec: 'vp9',
        bitrate: 3000,
        quality: 30,
        preset: 'medium',
        pixelFormat: 'yuv420p',
        audioEnabled: false,
      },
    },
  },
  {
    id: 'apng-standard',
    name: 'Standard APNG',
    description: 'Animated PNG with full color',
    category: 'gif',
    isBuiltIn: true,
    options: {
      format: 'apng',
      outputPath: '',
      apng: {
        colorDepth: 24,
        compressionLevel: 6,
        loopCount: 0,
        enableTransparency: true,
        detectUnchangedPixels: true,
      },
    },
  },
  {
    id: 'webp-standard',
    name: 'Standard WebP',
    description: 'Animated WebP for modern browsers',
    category: 'web',
    isBuiltIn: true,
    options: {
      format: 'webp',
      outputPath: '',
      webp: {
        quality: 80,
        lossless: false,
        loopCount: 0,
        method: 4,
      },
    },
  },
];

const initialState: ExportState = {
  currentOptions: null,
  selectedPresetId: 'gif-standard',
  outputPath: '',
  outputFileName: 'animation',
  builtInPresets: defaultBuiltInPresets,
  customPresets: [],
  defaultPresetId: 'gif-standard',
  isEncoding: false,
  currentJobId: null,
  encodingProgress: null,
  queue: [],
  isQueueProcessing: false,
  maxConcurrentJobs: 1,
  isUploading: false,
  uploadProgress: null,
  lastUploadResult: null,
  uploadConfig: null,
  recentExports: [],
  maxRecentExports: 20,
  showAdvancedOptions: false,
  selectedFormatTab: 'gif',
  error: null,
};

export const useExportStore = create<ExportState & ExportActions>()(
  subscribeWithSelector(
    persist(
      (set, get) => ({
        ...initialState,

        // Configuration
        setCurrentOptions: (currentOptions) => set({ currentOptions }),
        updateCurrentOptions: (updates) =>
          set((state) => ({
            currentOptions: state.currentOptions
              ? { ...state.currentOptions, ...updates }
              : null,
          })),
        setSelectedPresetId: (selectedPresetId) => set({ selectedPresetId }),
        setOutputPath: (outputPath) => set({ outputPath }),
        setOutputFileName: (outputFileName) => set({ outputFileName }),
        applyPreset: (preset) =>
          set({
            currentOptions: { ...preset.options },
            selectedPresetId: preset.id,
            selectedFormatTab: preset.options.format,
          }),

        // Presets
        setBuiltInPresets: (builtInPresets) => set({ builtInPresets }),
        addCustomPreset: (preset) =>
          set((state) => ({ customPresets: [...state.customPresets, preset] })),
        updateCustomPreset: (presetId, updates) =>
          set((state) => ({
            customPresets: state.customPresets.map((p) =>
              p.id === presetId ? { ...p, ...updates, modifiedAt: new Date().toISOString() } : p
            ),
          })),
        removeCustomPreset: (presetId) =>
          set((state) => ({
            customPresets: state.customPresets.filter((p) => p.id !== presetId),
          })),
        setDefaultPresetId: (defaultPresetId) => set({ defaultPresetId }),
        getPresetById: (presetId) => {
          const { builtInPresets, customPresets } = get();
          return [...builtInPresets, ...customPresets].find((p) => p.id === presetId);
        },
        getPresetsByCategory: (category) => {
          const { builtInPresets, customPresets } = get();
          return [...builtInPresets, ...customPresets].filter((p) => p.category === category);
        },

        // Encoding
        startEncoding: (jobId) =>
          set({
            isEncoding: true,
            currentJobId: jobId,
            encodingProgress: {
              jobId,
              state: 'preparing',
              progress: 0,
              currentFrame: 0,
              totalFrames: 0,
              stage: 'Preparing...',
              startedAt: new Date().toISOString(),
            },
            error: null,
          }),
        updateEncodingProgress: (encodingProgress) => set({ encodingProgress }),
        completeEncoding: (success, error) =>
          set((state) => ({
            isEncoding: false,
            encodingProgress: state.encodingProgress
              ? {
                  ...state.encodingProgress,
                  state: success ? 'completed' : 'failed',
                  progress: success ? 100 : state.encodingProgress.progress,
                  completedAt: new Date().toISOString(),
                  error,
                }
              : null,
            error: success ? null : error ?? null,
          })),
        cancelEncoding: () =>
          set((state) => ({
            isEncoding: false,
            encodingProgress: state.encodingProgress
              ? { ...state.encodingProgress, state: 'cancelled' }
              : null,
          })),

        // Queue
        addToQueue: (item) =>
          set((state) => ({
            queue: [
              ...state.queue,
              {
                ...item,
                id: crypto.randomUUID(),
                status: 'queued',
                progress: 0,
                addedAt: new Date().toISOString(),
              },
            ],
          })),
        removeFromQueue: (itemId) =>
          set((state) => ({ queue: state.queue.filter((i) => i.id !== itemId) })),
        clearQueue: () => set({ queue: [] }),
        updateQueueItem: (itemId, updates) =>
          set((state) => ({
            queue: state.queue.map((i) => (i.id === itemId ? { ...i, ...updates } : i)),
          })),
        startQueueProcessing: () => set({ isQueueProcessing: true }),
        stopQueueProcessing: () => set({ isQueueProcessing: false }),

        // Upload
        startUpload: (config) =>
          set({
            isUploading: true,
            uploadConfig: config,
            uploadProgress: {
              uploadId: crypto.randomUUID(),
              destination: config.destination,
              progress: 0,
              bytesUploaded: 0,
              totalBytes: 0,
              state: 'preparing',
            },
            error: null,
          }),
        updateUploadProgress: (uploadProgress) => set({ uploadProgress }),
        completeUpload: (lastUploadResult) =>
          set({
            isUploading: false,
            lastUploadResult,
            uploadProgress: null,
          }),
        cancelUpload: () =>
          set({
            isUploading: false,
            uploadProgress: null,
          }),
        setUploadConfig: (uploadConfig) => set({ uploadConfig }),

        // Recent exports
        addRecentExport: (exportInfo) =>
          set((state) => {
            const newRecent = [exportInfo, ...state.recentExports].slice(0, state.maxRecentExports);
            return { recentExports: newRecent };
          }),
        removeRecentExport: (exportId) =>
          set((state) => ({
            recentExports: state.recentExports.filter((e) => e.id !== exportId),
          })),
        clearRecentExports: () => set({ recentExports: [] }),

        // UI
        setShowAdvancedOptions: (showAdvancedOptions) => set({ showAdvancedOptions }),
        toggleAdvancedOptions: () =>
          set((state) => ({ showAdvancedOptions: !state.showAdvancedOptions })),
        setSelectedFormatTab: (selectedFormatTab) => set({ selectedFormatTab }),

        // Error handling
        setError: (error) => set({ error }),
        clearError: () => set({ error: null }),

        // Reset
        reset: () => set(initialState),
        resetProgress: () =>
          set({
            isEncoding: false,
            currentJobId: null,
            encodingProgress: null,
            isUploading: false,
            uploadProgress: null,
            error: null,
          }),
      }),
      {
        name: 'screentogif-export-store',
        partialize: (state) => ({
          customPresets: state.customPresets,
          defaultPresetId: state.defaultPresetId,
          recentExports: state.recentExports,
          showAdvancedOptions: state.showAdvancedOptions,
        }),
      }
    )
  )
);

// Selector hooks
export const selectIsEncoding = (state: ExportState) => state.isEncoding;
export const selectEncodingProgress = (state: ExportState) => state.encodingProgress?.progress ?? 0;
export const selectAllPresets = (state: ExportState) => [
  ...state.builtInPresets,
  ...state.customPresets,
];

/**
 * Stores Index
 * Re-exports all Zustand stores for convenient imports
 */

// Recorder Store
export { useRecorderStore, selectCaptureState, selectIsRecording, selectCaptureOptions } from './recorderStore';

// Editor Store
export {
  useEditorStore,
  selectIsPlaying,
  selectSelectedFrameCount,
  selectHasSelection,
} from './editorStore';
export type { PlaybackState, SelectionMode, EditorTool, ZoomPreset } from './editorStore';

// Project Store
export {
  useProjectStore,
  selectHasProject,
  selectIsDirty,
  selectFrameCount,
  selectProjectTitle,
} from './projectStore';

// Export Store
export {
  useExportStore,
  selectIsEncoding,
  selectEncodingProgress,
  selectAllPresets,
} from './exportStore';

// Settings Store
export {
  useSettingsStore,
  selectTheme,
  selectLocale,
  selectHotkeys,
} from './settingsStore';
export type { AppTheme, AppLocale, StartupMode, ThumbnailQuality, HotkeyBinding } from './settingsStore';

// UI Store
export {
  useUIStore,
  selectCurrentView,
  selectIsLoading,
  selectToasts,
  selectIsBackendConnected,
} from './uiStore';
export type { Toast, ToastType, ModalType, AppView, PanelId } from './uiStore';

