     1→/**
     2→ * Localization Service
     3→ * Internationalization and translation management
     4→ */
     5→
     6→import type { AppLocale } from '../stores/settingsStore';
     7→
     8→/** Supported locales with their display names */
     9→export const SUPPORTED_LOCALES: Record<AppLocale, string> = {
    10→  en: 'English',
    11→  de: 'Deutsch',
    12→  es: 'Español',
    13→  fr: 'Français',
    14→  pt: 'Português',
    15→  ru: 'Русский',
    16→  zh: '中文',
    17→  ja: '日本語',
    18→  ko: '한국어',
    19→};
    20→
    21→/** Translation dictionary type */
    22→interface TranslationDictionary {
    23→  [key: string]: string | TranslationDictionary;
    24→}
    25→
    26→/** Pluralization rules */
    27→type PluralRule = (n: number) => 'zero' | 'one' | 'two' | 'few' | 'many' | 'other';
    28→
    29→/** Interpolation options */
    30→interface InterpolationOptions {
    31→  [key: string]: string | number;
    32→}
    33→
    34→class LocalizationServiceImpl {
    35→  private currentLocale: AppLocale = 'en';
    36→  private translations: Map<AppLocale, TranslationDictionary> = new Map();
    37→  private fallbackLocale: AppLocale = 'en';
    38→  private _isInitialized = false;
    39→  private loadingPromises: Map<AppLocale, Promise<void>> = new Map();
    40→  private pluralRules: Map<AppLocale, PluralRule> = new Map();
    41→
    42→  constructor() {
    43→    this.initPluralRules();
    44→  }
    45→
    46→  /**
    47→   * Initialize the service with a locale
    48→   */
    49→  async initialize(locale: AppLocale = 'en'): Promise<void> {
    50→    await this.loadTranslations(locale);
    51→
    52→    // Also load fallback locale
    53→    if (locale !== this.fallbackLocale) {
    54→      await this.loadTranslations(this.fallbackLocale);
    55→    }
    56→
    57→    this.currentLocale = locale;
    58→    this._isInitialized = true;
    59→  }
    60→
    61→  /**
    62→   * Check if service is initialized
    63→   */
    64→  isInitialized(): boolean {
    65→    return this._isInitialized;
    66→  }
    67→
    68→  /**
    69→   * Get current locale
    70→   */
    71→  getLocale(): AppLocale {
    72→    return this.currentLocale;
    73→  }
    74→
    75→  /**
    76→   * Set current locale
    77→   */
    78→  async setLocale(locale: AppLocale): Promise<void> {
    79→    if (!SUPPORTED_LOCALES[locale]) {
    80→      console.warn(`Unsupported locale: ${locale}`);
    81→      return;
    82→    }
    83→
    84→    await this.loadTranslations(locale);
    85→    this.currentLocale = locale;
    86→
    87→    // Update document lang attribute
    88→    document.documentElement.lang = locale;
    89→  }
    90→
    91→  /**
    92→   * Load translations for a locale
    93→   */
    94→  async loadTranslations(locale: AppLocale): Promise<void> {
    95→    // Check if already loaded
    96→    if (this.translations.has(locale)) {
    97→      return;
    98→    }
    99→
   100→    // Check if loading is in progress
   101→    const existingPromise = this.loadingPromises.get(locale);
   102→    if (existingPromise) {
   103→      return existingPromise;
   104→    }
   105→
   106→    // Load translations
   107→    const loadPromise = this.fetchTranslations(locale);
   108→    this.loadingPromises.set(locale, loadPromise);
   109→
   110→    try {
   111→      await loadPromise;
   112→    } finally {
   113→      this.loadingPromises.delete(locale);
   114→    }
   115→  }
   116→
   117→  /**
   118→   * Translate a key
   119→   */
   120→  t(key: string, options?: InterpolationOptions): string {
   121→    const translation = this.getTranslation(key);
   122→
   123→    if (!translation) {
   124→      console.warn(`Missing translation for key: ${key}`);
   125→      return key;
   126→    }
   127→
   128→    if (options) {
   129→      return this.interpolate(translation, options);
   130→    }
   131→
   132→    return translation;
   133→  }
   134→
   135→  /**
   136→   * Translate with pluralization
   137→   */
   138→  tp(key: string, count: number, options?: InterpolationOptions): string {
   139→    const pluralForm = this.getPluralForm(count);
   140→    const pluralKey = `${key}.${pluralForm}`;
   141→
   142→    // Try plural form first, then fall back to base key
   143→    let translation = this.getTranslation(pluralKey);
   144→    if (!translation) {
   145→      translation = this.getTranslation(`${key}.other`);
   146→    }
   147→    if (!translation) {
   148→      translation = this.getTranslation(key);
   149→    }
   150→
   151→    if (!translation) {
   152→      console.warn(`Missing translation for key: ${key}`);
   153→      return key;
   154→    }
   155→
   156→    const interpolationOptions = { ...options, count };
   157→    return this.interpolate(translation, interpolationOptions);
   158→  }
   159→
   160→  /**
   161→   * Check if a translation exists
   162→   */
   163→  hasTranslation(key: string): boolean {
   164→    return this.getTranslation(key) !== null;
   165→  }
   166→
   167→  /**
   168→   * Get all supported locales
   169→   */
   170→  getSupportedLocales(): { code: AppLocale; name: string }[] {
