     1→/**
     2→ * RecorderPage Component
     3→ * Full recorder page with region selection, recording controls, and keyboard shortcuts
     4→ */
     5→
     6→import { useState, useCallback, useMemo, type ChangeEvent } from 'react';
     7→import { useRecorderStore } from '../../../stores/recorderStore';
     8→import { useHotkeys } from '../../../hooks/useHotkeys';
     9→import { Icon } from '../../../components/atoms/Icon';
    10→import { Slider } from '../../../components/atoms/Slider';
    11→import { Toggle } from '../../../components/atoms/Toggle';
    12→import { Tooltip } from '../../../components/molecules/Tooltip';
    13→import { StatusBar, type StatusType } from '../../../components/organisms/StatusBar';
    14→import { RegionSelector } from '../components/RegionSelector';
    15→import { RecordingControls } from '../components/RecordingControls';
    16→import { RecordingTimer } from '../components/RecordingTimer';
    17→import { CaptureSourceSelector } from '../components/CaptureSourceSelector';
    18→import { WebcamPreview } from '../components/WebcamPreview';
    19→import { useCapture } from '../hooks/useCapture';
    20→import { useWebcam } from '../hooks/useWebcam';
    21→
    22→export interface RecorderPageProps {
    23→  onClose?: () => void;
    24→  onRecordingComplete?: (frameCount: number, duration: number) => void;
    25→  className?: string;
    26→}
    27→
    28→export function RecorderPage({
    29→  onClose,
    30→  onRecordingComplete,
    31→  className = '',
    32→}: RecorderPageProps) {
    33→  const [showSettings, setShowSettings] = useState(false);
    34→  const [showWebcam, setShowWebcam] = useState(false);
    35→  const [webcamPosition, setWebcamPosition] = useState<'top-left' | 'top-right' | 'bottom-left' | 'bottom-right'>('bottom-right');
    36→  const [webcamSize, setWebcamSize] = useState<'small' | 'medium' | 'large'>('medium');
    37→
    38→  // Store state
    39→  const {
    40→    captureMode,
    41→    selectedRegion,
    42→    selectedDisplayId,
    43→    selectedWindowId,
    44→    frameRate,
    45→    captureMouseCursor,
    46→    captureMouseClicks,
    47→    availableDisplays,
    48→    availableWindows,
    49→    frameCount,
    50→    recordingDuration,
    51→    error,
    52→    setCaptureMode,
    53→    setSelectedRegion,
    54→    setSelectedDisplayId,
    55→    setSelectedWindowId,
    56→    setFrameRate,
    57→    setCaptureMouseCursor,
    58→    setCaptureMouseClicks,
    59→    clearError,
    60→  } = useRecorderStore();
    61→
    62→  // Capture hook
    63→  const {
    64→    captureState,
    65→    isPaused,
    66→    canStart,
    67→    start,
    68→    stop,
    69→    togglePause,
    70→    discard,
    71→    refreshSources,
    72→  } = useCapture({
    73→    onStop: (frames, duration) => {
    74→      onRecordingComplete?.(frames, duration);
    75→    },
    76→    onError: (err) => {
    77→      console.error('Capture error:', err);
    78→    },
    79→  });
    80→
    81→  // Webcam hook
    82→  const webcam = useWebcam({
    83→    onError: (err) => {
    84→      console.error('Webcam error:', err);
    85→    },
    86→  });
    87→
    88→  // Computed states
    89→  const isRecording = captureState === 'recording' || captureState === 'paused';
    90→  const isIdle = captureState === 'idle';
    91→  const isStarting = captureState === 'starting';
    92→  const isStopping = captureState === 'stopping';
    93→
    94→  // Status bar configuration
    95→  const status: StatusType = isRecording
    96→    ? isPaused
    97→      ? 'warning'
    98→      : 'recording'
    99→    : isStarting || isStopping
   100→      ? 'processing'
   101→      : error
   102→        ? 'error'
   103→        : 'idle';
   104→
   105→  const statusMessage = isRecording
   106→    ? isPaused
   107→      ? 'Paused'
   108→      : 'Recording'
   109→    : isStarting
   110→      ? 'Starting...'
   111→      : isStopping
   112→        ? 'Stopping...'
   113→        : error
   114→          ? error
   115→          : 'Ready';
   116→
   117→  // Keyboard shortcuts
   118→  const handleRecordHotkey = useCallback(() => {
   119→    if (isIdle && canStart) {
   120→      start();
   121→    } else if (isRecording) {
   122→      togglePause();
   123→    }
   124→  }, [isIdle, isRecording, canStart, start, togglePause]);
   125→
   126→  const handleStopHotkey = useCallback(() => {
   127→    if (isRecording) {
   128→      stop();
   129→    }
   130→  }, [isRecording, stop]);
   131→
   132→  const handleDiscardHotkey = useCallback(() => {
   133→    if (isRecording) {
   134→      discard();
   135→    }
   136→  }, [isRecording, discard]);
   137→
   138→  const hotkeys = useMemo(
   139→    () => [
   140→      {
   141→        key: 'F7',
   142→        callback: handleRecordHotkey,
   143→        description: 'Start/Pause Recording',
   144→      },
   145→      {
   146→        key: 'F8',
   147→        callback: handleStopHotkey,
   148→        description: 'Stop Recording',
   149→      },
   150→      {
   151→        key: 'F9',
   152→        callback: handleDiscardHotkey,
   153→        description: 'Discard Recording',
   154→      },
   155→      {
   156→        key: 'Escape',
   157→        callback: () => {
   158→          if (showSettings) {
   159→            setShowSettings(false);
   160→          } else if (!isRecording && onClose) {
   161→            onClose();
   162→          }
   163→        },
   164→        description: 'Close/Cancel',
   165→      },
   166→    ],
   167→    [handleRecordHotkey, handleStopHotkey, handleDiscardHotkey, showSettings, isRecording, onClose]
   168→  );
   169→
   170→  useHotkeys(hotkeys);
   171→
   172→  // Capture dimensions
   173→  const captureDimensions = useMemo(() => {
   174→    if (captureMode === 'region' && selectedRegion) {
   175→      return { width: selectedRegion.width, height: selectedRegion.height };
   176→    }
   177→    if (captureMode === 'screen' && selectedDisplayId) {
   178→      const display = availableDisplays.find((d) => d.id === selectedDisplayId);
   179→      if (display) {
   180→        return { width: display.width, height: display.height };
   181→      }
   182→    }
   183→    if (captureMode === 'window' && selectedWindowId) {
   184→      const window = availableWindows.find((w) => w.id === selectedWindowId);
   185→      if (window) {
   186→        return { width: window.bounds.width, height: window.bounds.height };
   187→      }
   188→    }
   189→    return null;
   190→  }, [captureMode, selectedRegion, selectedDisplayId, selectedWindowId, availableDisplays, availableWindows]);
   191→
   192→  return (
   193→    <div className={`flex flex-col h-screen bg-surface-900 ${className}`}>
   194→      {/* Header */}
   195→      <header className="flex items-center justify-between h-12 px-4 bg-surface-800 border-b border-surface-700">
   196→        <div className="flex items-center gap-3">
   197→          <Icon name="record" size="md" className="text-accent-error" />
   198→          <span className="text-sm font-medium text-surface-200">Screen Recorder</span>
   199→
   200→          {/* Recording timer */}
   201→          {isRecording && (
   202→            <div className="ml-4 pl-4 border-l border-surface-600">
   203→              <RecordingTimer
   204→                duration={recordingDuration}
   205→                isRecording
   206→                isPaused={isPaused}
   207→                frameCount={frameCount}
   208→                fps={frameRate}
   209→                size="sm"
   210→              />
   211→            </div>
   212→          )}
   213→        </div>
   214→
   215→        <div className="flex items-center gap-2">
   216→          {/* Webcam toggle */}
   217→          <Tooltip content={showWebcam ? 'Hide webcam' : 'Show webcam'} position="bottom">
   218→            <button
   219→              onClick={() => {
   220→                if (!showWebcam) {
   221→                  webcam.startStream();
   222→                } else {
   223→                  webcam.stopStream();
   224→                }
   225→                setShowWebcam(!showWebcam);
   226→              }}
   227→              className={`
   228→                p-2 rounded transition-colors
   229→                ${showWebcam
   230→                  ? 'bg-primary-500/20 text-primary-400'
   231→                  : 'text-surface-400 hover:text-surface-200 hover:bg-surface-700'
   232→                }
   233→              `}
   234→            >
   235→              <Icon name={showWebcam ? 'eye' : 'eye-slash'} size="sm" />
   236→            </button>
   237→          </Tooltip>
   238→
   239→          {/* Settings toggle */}
   240→          <Tooltip content="Settings" position="bottom">
   241→            <button
   242→              onClick={() => setShowSettings(!showSettings)}
   243→              className={`
   244→                p-2 rounded transition-colors
   245→                ${showSettings
   246→                  ? 'bg-primary-500/20 text-primary-400'
   247→                  : 'text-surface-400 hover:text-surface-200 hover:bg-surface-700'
   248→                }
   249→              `}
   250→            >
   251→              <Icon name="cog" size="sm" />
   252→            </button>
   253→          </Tooltip>
   254→
   255→          {/* Close button */}
   256→          {onClose && (
   257→            <Tooltip content="Close (Esc)" position="bottom">
   258→              <button
   259→                onClick={onClose}
   260→                disabled={isRecording}
   261→                className="p-2 text-surface-400 hover:text-surface-200 hover:bg-accent-error/20 rounded transition-colors disabled:opacity-50"
   262→              >
   263→                <Icon name="close" size="sm" />
   264→              </button>
   265→            </Tooltip>
   266→          )}
   267→        </div>
   268→      </header>
   269→
   270→      {/* Main content area */}
   271→      <div className="flex-1 flex overflow-hidden">
   272→        {/* Settings sidebar */}
   273→        {showSettings && (
   274→          <aside className="w-80 bg-surface-800 border-r border-surface-700 overflow-y-auto">
   275→            <div className="p-4 space-y-6">
   276→              {/* Capture Source */}
   277→              <div>
   278→                <h3 className="text-sm font-medium text-surface-200 mb-3">Capture Source</h3>
   279→                <CaptureSourceSelector
   280→                  mode={captureMode}
