   282→                  windows={availableWindows}
   283→                  selectedDisplayId={selectedDisplayId}
   284→                  selectedWindowId={selectedWindowId}
   285→                  onModeChange={setCaptureMode}
   286→                  onDisplaySelect={setSelectedDisplayId}
   287→                  onWindowSelect={setSelectedWindowId}
   288→                  onRefresh={refreshSources}
   289→                  isLoading={isStarting}
   290→                />
   291→              </div>
   292→
   293→              {/* Recording Settings */}
   294→              <div className="space-y-4">
   295→                <h3 className="text-sm font-medium text-surface-200">Recording Settings</h3>
   296→
   297→                {/* Frame rate */}
   298→                <div>
   299→                  <label className="block text-xs text-surface-400 mb-2">
   300→                    Frame Rate: {frameRate} fps
   301→                  </label>
   302→                  <Slider
   303→                    value={frameRate}
   304→                    onChange={(e: ChangeEvent<HTMLInputElement>) => setFrameRate(Number(e.target.value))}
   305→                    min={1}
   306→                    max={60}
   307→                    step={1}
   308→                    disabled={isRecording}
   309→                  />
   310→                </div>
   311→
   312→                {/* Mouse cursor */}
   313→                <div className="flex items-center justify-between">
