   430→            <Icon name="photo" size="sm" />
   431→            <span className="font-mono">
   432→              {captureDimensions.width} x {captureDimensions.height}
   433→            </span>
   434→          </div>
   435→        )}
   436→
   437→        {/* Recording timer (larger, when recording) */}
   438→        {isRecording && (
   439→          <RecordingTimer
   440→            duration={recordingDuration}
   441→            isRecording
   442→            isPaused={isPaused}
   443→            frameCount={frameCount}
   444→            fps={frameRate}
   445→            size="lg"
   446→          />
   447→        )}
   448→
   449→        {/* Main controls */}
   450→        <RecordingControls
   451→          captureState={captureState}
   452→          isPaused={isPaused}
   453→          canStart={canStart}
   454→          onRecord={start}
   455→          onPause={togglePause}
   456→          onStop={stop}
   457→          onDiscard={discard}
   458→        />
   459→
   460→        {/* Frame rate display */}
   461→        {isIdle && (
   462→          <div className="flex items-center gap-2 text-sm text-surface-400">
   463→            <Icon name="clock" size="sm" />
   464→            <span className="font-mono">{frameRate} fps</span>
   465→          </div>
   466→        )}
   467→      </div>
   468→
   469→      {/* Status bar */}
   470→      <StatusBar
   471→        status={status}
   472→        statusMessage={statusMessage}
   473→        rightItems={[
   474→          {
   475→            id: 'shortcuts',
   476→            content: 'F7: Record | F8: Stop | F9: Discard',
   477→            tooltip: 'Keyboard shortcuts',
